-- Each world's stand-in receiving system (#590, answer 618): its key, made
-- the first time the world needs it, and the receipts of what it took,
-- which name no pupil, generated by `prisma migrate diff --script` against
-- 0002_stand_in_ca.

-- AlterTable
ALTER TABLE "world" ADD COLUMN     "receiverKey" TEXT;

-- CreateTable
CREATE TABLE "receipt" (
    "seq" SERIAL NOT NULL,
    "worldId" CHAR(5) NOT NULL,
    "id" CHAR(32) NOT NULL,
    "kind" VARCHAR(16) NOT NULL,
    "term" INTEGER NOT NULL,
    "class" VARCHAR(32) NOT NULL,
    "subject" VARCHAR(32) NOT NULL,
    "rows" INTEGER NOT NULL,
    "signed" DATE NOT NULL,
    "received" DATE NOT NULL,
    "signer" CHAR(32) NOT NULL,

    CONSTRAINT "receipt_pkey" PRIMARY KEY ("seq")
);

-- CreateIndex
CREATE INDEX "receipt_worldId_seq_idx" ON "receipt"("worldId", "seq");

-- CreateIndex
CREATE UNIQUE INDEX "receipt_worldId_id_key" ON "receipt"("worldId", "id");

-- AddForeignKey
ALTER TABLE "receipt" ADD CONSTRAINT "receipt_worldId_fkey" FOREIGN KEY ("worldId") REFERENCES "world"("id") ON DELETE CASCADE ON UPDATE CASCADE;
